css:
@page {
  size: A4;
  margin: 0;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  margin-top: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  margin-right: 0mm !important;
  min-height: 0 !important;
  max-width: none !important;
}

.action-banner {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.print-format-preview {
  padding: 0 !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

.print-page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;

  background-image: var(--page-bg);
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 210mm 297mm;

  page-break-after: always;
}

.print-page:last-child {
  page-break-after: auto;
}

.field {
  position: absolute;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
  white-space: normal;
}

.field-customer-code {
  top: 58mm;
  left: 40mm;
  width: 50mm;
}

.field-customer {
  top: 62mm;
  left: 18mm;
  width: 92mm;
  font-size: 9px;
}

.field-receipt-no {
  top: 57mm;
  left: 144mm;
  width: 58mm;
  font-weight: bold;
}

.field-date {
  top: 65mm;
  left: 144mm;
  width: 58mm;
}

.field-salesman {
  top: 80.5mm;
  left: 144mm;
  width: 58mm;
  font-size: 9px;
}

.item-table-wrapper {
  position: absolute;
  top: 107mm;
  left: 14mm;
  width: 189mm;
}

.item-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
  color: #000;
}

.item-table td {
  border: none;
  padding: 1.5mm;
  vertical-align: top;
  line-height: 1.25;
}

.col-no {
  width: 12mm;
  text-align: center;
}

.col-invoice {
  width: 34mm;
  text-align: left;
}

.col-date {
  width: 23mm;
  text-align: center;
}

.col-duedate {
  width: 21mm;
  text-align: center;
}

.col-amount {
  width: 30mm;
  text-align: right;
}

.col-remain {
  width: 36mm;
  text-align: right;
}

.col-paid {
  width: 33mm;
  text-align: right;
}

.field-amount-text {
  top: 227.5mm;
  left: 16mm;
  width: 122mm;
}

.field-total {
  top: 227.5mm;
  left: 170mm;
  width: 32mm;
  text-align: right;
  font-weight: bold;
}

.field-pay-cash {
  top: 242.3mm;
  left: 99mm;
  width: 5mm;
  text-align: center;
  font-weight: bold;
}

.field-pay-cheque {
  top: 242.3mm;
  left: 122.5mm;
  width: 5mm;
  text-align: center;
  font-weight: bold;
}

.field-prepared {
  top: 275.5mm;
  left: 150mm;
  width: 52mm;
  font-size: 8px;
}

html:
{%- macro be_date(dt) -%}
{%- if dt -%}{%- set td = frappe.utils.getdate(dt) -%}{{ "%02d/%02d/%04d" % (td.day, td.month, td.year + 543) }}{%- endif -%}
{%- endmacro -%}

{%- set background = "/assets/connect_diagnostics_core/images/print_formats/receipt-1.png" -%}
{%- set tax_id = frappe.db.get_value("Customer", doc.party, "tax_id") if doc.party_type == "Customer" else "" -%}
{%- set addr_name = frappe.db.get_value("Customer", doc.party, "customer_primary_address") if doc.party_type == "Customer" else None -%}
{%- set addr = frappe.db.get_value("Address", addr_name, ["address_line1", "address_line2", "city", "state", "pincode"], as_dict=True) if addr_name else None -%}

{%- set salespersons = [] -%}
{%- for row in doc.references -%}
  {%- if row.reference_doctype == "Sales Invoice" -%}
    {%- for sp in frappe.get_all("Sales Team", filters={"parent": row.reference_name, "parenttype": "Sales Invoice"}, fields=["sales_person"]) -%}
      {%- if sp.sales_person and sp.sales_person not in salespersons -%}{%- set _ = salespersons.append(sp.sales_person) -%}{%- endif -%}
    {%- endfor -%}
  {%- endif -%}
{%- endfor -%}

{%- set is_cash = (doc.mode_of_payment or "") | lower in ["cash", "เงินสด"] -%}
{%- set prepared_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner -%}

  <div
    class="print-page"
    style="--page-bg: url('{{ background }}');"
  >

    <!-- Customer -->
    <div class="field field-customer-code">
      {{ doc.party or "" }}
    </div>

    <div class="field field-customer">
      <div><b>{{ doc.party_name or "" }}</b></div>
      {% if addr %}
        <div>{{ addr.address_line1 or "" }} {{ addr.address_line2 or "" }} {{ addr.city or "" }} {{ addr.state or "" }}</div>
        {% if addr.pincode %}<div>{{ addr.pincode }}</div>{% endif %}
      {% endif %}
      {% if tax_id %}<div>เลขประจำตัวผู้เสียภาษี {{ tax_id }}</div>{% endif %}
    </div>

    <!-- Receipt info -->
    <div class="field field-receipt-no">
      {{ doc.name }}
    </div>

    <div class="field field-date">
      {{ be_date(doc.posting_date) }}
    </div>

    <div class="field field-salesman">
      {{ salespersons | join(", ") }}
    </div>

    <!-- Invoice references -->
    <div class="item-table-wrapper">
      <table class="item-table">
        <tbody>
          {% for row in doc.references %}
            {% set inv_date = frappe.db.get_value(row.reference_doctype, row.reference_name, "posting_date") %}
            <tr>
              <td class="col-no">{{ loop.index }}</td>
              <td class="col-invoice">{{ row.reference_name }}</td>
              <td class="col-date">{{ be_date(inv_date) }}</td>
              <td class="col-duedate">{{ be_date(row.due_date) }}</td>
              <td class="col-amount">{{ print_currency(row.total_amount, doc.paid_to_account_currency or "THB") }}</td>
              <td class="col-remain">{% if row.outstanding_amount %}{{ print_currency(row.outstanding_amount, doc.paid_to_account_currency or "THB") }}{% endif %}</td>
              <td class="col-paid">{{ print_currency(row.allocated_amount, doc.paid_to_account_currency or "THB") }}</td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>

    <!-- Total + words -->
    <div class="field field-amount-text">
      ({{ number_to_thai_currency(doc.paid_amount or 0, doc.paid_to_account_currency or "THB") }}).
    </div>

    <div class="field field-total">
      {{ print_currency(doc.paid_amount or 0, doc.paid_to_account_currency or "THB") }}
    </div>

    <!-- Payment method -->
    <div class="field field-pay-cash">{% if is_cash %}X{% endif %}</div>
    <div class="field field-pay-cheque">{% if not is_cash %}X{% endif %}</div>

    <!-- Prepared by -->
    <div class="field field-prepared">
      {{ prepared_name }} {{ be_date(doc.creation) }} {{ frappe.utils.get_datetime(doc.creation).strftime("%H:%M:%S") }}
    </div>

  </div>
